                        arctrig3: "$\\int \\frac{1}{x^2+1} dx = \\arctan(x)$",
                        arctrig4: "$\\int \\frac{-1}{x^2+1} dx = \\text{arccot}(x)$",
                        arctrig5: "$\\int \\frac{1}{|x|\\sqrt{x^2-1}} dx = \\text{arcsec}(x)$",
                        
                        // --- 5. Hyperbolic ---
                        cheat_title5: "Hyperbolic Integrals",
