                        ex4_1_step2: "Evaluate at $x=0$: $f(0) = 1$, $f'(0) = 1$, $f''(0) = 1$.",
                        ex4_1_step3: "Plug into formula: $1 + 1x + \\frac{1}{2!}x^2 + \\frac{1}{3!}x^3 + \\dots$",
                        ex4_1_result: "Series: $\\sum_{n=0}^{\\infty} \\frac{x^n}{n!}$"
