                            problem: "Find the general solution:",
                            problem_math: `y'' - 5y' + 6y = 0`,
                            step1_title: "Step 1: Characteristic Equation",
                            step1_desc: "Replace derivatives with powers of $r$.",
                            step1_math: `r^2 - 5r + 6 = 0`,
                            step2_title: "Step 2: Find Roots",
