                        cond4_3: "3. Isoliere $\\frac{dy}{dx}$ algebraisch.",
                        types_title: "Häufiger Fehler",
                        type1: "Denke daran: $\\frac{d}{dx}(y^3) \\neq 3y^2$. Es ist $3y^2 \\cdot \\frac{dy}{dx}$, weil y eine Funktion von x ist.",
