                            step2_title: "Schritt 2: Differenziere u",
                            step2_desc: "Finde $du$. Da $u = x^2 + 1$, ist $du = 2x dx$. Wir haben $x dx$ im Problem, also $\\frac{1}{2}du = x dx$.",
