                        ex4_1_step3: "In die Formel einsetzen: $1 + 1x + \\frac{1}{2!}x^2 + \\frac{1}{3!}x^3 + \\dots$",
                        ex4_1_result: "Reihe: $\\sum_{n=0}^{\\infty} \\frac{x^n}{n!}$"
