                        list1_2: "Granica lewostronna: $\\lim_{x \\to c^-} f(x) = M$",
                        theorem1_1: "Twierdzenie: Granica ogólna $\\lim_{x \\to c} f(x)$ istnieje wtedy i tylko wtedy, gdy obie granice jednostronne istnieją i są równe (L = M)."
